{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Wellness coaching focused on habits, frameworks, and sustainable outcomes with {{COACH_NAME}}, {{CREDENTIALS}} in {{CITY}}, {{STATE}}." />
  <link rel="icon" href="data:;base64,iVBORw0KGgo=" />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="theme-earthy">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="main-nav">
        <a href="/about.html">About</a>
        <a href="/programs.html">Work With Me</a>
        <a href="/services.html">Services</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/testimonials.html">Stories</a>
        <a href="/book.html" class="cta">Book</a>
        <button id="nav-toggle" aria-expanded="false">☰</button>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>Small daily shifts. Deep, lasting balance.</h1>
          <p class="lede">I help busy people build resilient routines that improve sleep, energy, and focus without overwhelm. Practical frameworks. Gentle accountability.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/programs.html">Explore Programs</a>
          </div>
          <ul class="hero-features">
            <li>Evidence-informed habit frameworks</li>
            <li>Short practices you can do anywhere</li>
            <li>Flexible coaching for real life</li>
          </ul>
        </div>
        <figure class="hero-art" aria-hidden="true">
          <img src="assets/img/hero.svg" alt="Organic illustration of a leaf and sun" />
        </figure>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section id="social-proof" class="social-proof">
      <div class="wrap">
        <h2>Real results from steady steps</h2>
        <div class="testimonials">
          <blockquote>
            <img src="assets/img/avatar.svg" alt="" class="avatar" />
            <p>"After three months I sleep better and have energy to play with my kids — not just a quick boost but steady change."</p>
            <cite>— A client in {{CITY}}</cite>
          </blockquote>
          <blockquote>
            <img src="assets/img/avatar.svg" alt="" class="avatar" />
            <p>"The frameworks made habit changes approachable. I still use the checklist months later."</p>
            <cite>— A professional in {{STATE}}</cite>
          </blockquote>
          <blockquote>
            <img src="assets/img/avatar.svg" alt="" class="avatar" />
            <p>"Practical, compassionate coaching — nothing mystical, just what I needed to get moving."</p>
            <cite>— Client of {{COACH_NAME}}</cite>
          </blockquote>
        </div>
        <p class="micro">Featured in local workshops and community newsletters.</p>
      </div>
    </section>

    <!-- BENEFITS -->
    <section id="benefits" class="benefits">
      <div class="wrap">
        <h2>What you gain</h2>
        <div class="cards">
          <article>
            <h3>Predictable Momentum</h3>
            <p>Simple micro-habits that compound so you move forward without friction.</p>
          </article>
          <article>
            <h3>Stress-Less Routines</h3>
            <p>Routines designed around your life — flexible, forgiving, measurable.</p>
          </article>
          <article>
            <h3>Tools, Not Willpower</h3>
            <p>Frameworks that reduce decision fatigue and make habit formation automatic.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- PROCESS -->
    <section id="process" class="process">
      <div class="wrap">
        <h2>How we work together</h2>
        <ol class="process-steps">
          <li>
            <strong>Discover</strong>
            <p>We map current routines, constraints, and your real priorities.</p>
          </li>
          <li>
            <strong>Design</strong>
            <p>I craft a short, three-week starter plan tailored to your schedule.</p>
          </li>
          <li>
            <strong>Practice</strong>
            <p>Daily micro-tasks with gentle check-ins to build consistency.</p>
          </li>
          <li>
            <strong>Embed</strong>
            <p>Shift from guided change to independent, sustainable habits.</p>
          </li>
        </ol>
      </div>
    </section>

    <!-- LEAD MAGNET -->
    <section id="lead-magnet" class="lead-magnet">
      <div class="wrap">
        <div class="magnet-grid">
          <div>
            <h2>Free Guide: The 5-Minute Reset</h2>
            <p>Download a short toolkit that helps you recover focus and calm in five minutes — evidence-informed practices you can use right away.</p>
            <form id="lead-form" class="lead-form">
              <label for="email">Email</label>
              <input id="email" name="email" type="email" placeholder="you@example.com" required />
              <button class="btn primary" type="submit">{{PRIMARY_CTA_LABEL}}</button>
            </form>
            <p class="fine-print">No spam. Unsubscribe anytime.</p>
          </div>
          <aside class="magnet-art">
            <img src="assets/img/pattern.svg" alt="Illustrative pattern" />
          </aside>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section id="faq" class="faq">
      <div class="wrap">
        <h2>Questions I hear often</h2>
        <div class="faq-list">
          <details>
            <summary>Is this coaching medical advice?</summary>
            <p>No. Coaching focuses on habits, lifestyle patterns, and skill-building. It is not a replacement for medical or mental health care.</p>
          </details>
          <details>
            <summary>How long until I see progress?</summary>
            <p>Many clients notice small wins in the first 2–3 weeks; lasting shifts are typically built over 3 months.</p>
          </details>
          <details>
            <summary>Do you offer sliding scale or packages?</summary>
            <p>Yes — I offer flexible program tiers and limited sliding-scale spots. See the Pricing page for current options.</p>
          </details>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section id="cta" class="cta-band">
      <div class="wrap">
        <h2>Ready to start small and feel different?</h2>
        <p>Book a clarity call to map a plan that fits your life — practical, kind, and effective.</p>
        <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
      </div>
      <div>
        <nav>
          <a href="/about.html">About</a>
          <a href="/programs.html">Work With Me</a>
          <a href="/pricing.html">Pricing</a>
          <a href="/contact.html">Contact</a>
        </nav>
      </div>
      <div>
        <p>Call: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
    <div class="meta">
      <p>© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
