{"path":"assets/css/styles.css","content":"/* Earthy warm design — organic shapes, soft palette */
:root{
  --bg:#fff8f2;
  --muted:#7a6b5a;
  --accent:#c0563f; /* warm clay */
  --accent-2:#e7b67a; /* sand */
  --card:#fff;
  --glass:rgba(255,255,255,0.7);
  --radius:14px;
  --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; background:var(--bg); color:#2b2b2b; -webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max); margin:0 auto; padding:2rem}
.site-header{background:linear-gradient(180deg, rgba(255,248,242,0.6), transparent); backdrop-filter: blur(4px); border-bottom:1px solid rgba(200,180,160,0.2)}
.site-header .wrap{display:flex; align-items:center; gap:1rem; justify-content:space-between}
.brand{font-weight:700; color:var(--accent); text-decoration:none}
.nav a{margin:0 0.5rem; color:var(--muted); text-decoration:none}
.nav .cta{background:var(--accent); color:#fff; padding:0.5rem 0.9rem; border-radius:8px; text-decoration:none}
#nav-toggle{display:none; background:none; border:0; font-size:1.1rem}
.hero{padding:3rem 0}
.hero-grid{display:grid; grid-template-columns:1fr 380px; gap:2rem; align-items:center}
.lede{color:var(--muted); font-size:1.05rem}
.hero-ctas .btn{margin-right:0.5rem}
.btn{display:inline-block; padding:0.6rem 1rem; border-radius:10px; text-decoration:none; border:1px solid transparent}
.btn.primary{background:var(--accent); color:white}
.btn.ghost{background:transparent; color:var(--accent); border-color:rgba(192,88,63,0.1)}
.btn.large{padding:0.9rem 1.4rem; font-size:1.05rem}
.hero-features{list-style:none; padding:0; margin-top:1rem; color:var(--muted); display:flex; gap:1rem}
.hero-art img{width:100%; max-width:360px; display:block}
.social-proof{padding:2rem 0}
.social-proof h2{color:var(--accent-2)}
.testimonials{display:grid; grid-template-columns:repeat(auto-fit, minmax(220px,1fr)); gap:1rem}
.testimonials blockquote{background:var(--card); padding:1rem; border-radius:12px; box-shadow:0 6px 18px rgba(100,70,50,0.06)}
.avatar{width:48px; height:48px; border-radius:50%; margin-bottom:0.5rem}
.micro{color:var(--muted); margin-top:0.5rem}
.benefits{padding:2rem 0}
.cards{display:grid; grid-template-columns:repeat(3,1fr); gap:1rem}
.cards article{background:linear-gradient(180deg, rgba(255,255,255,0.8), var(--glass)); padding:1.2rem; border-radius:12px}
.process{padding:2rem 0; background:linear-gradient(180deg, rgba(231,182,122,0.06), transparent)}
.process-steps{display:grid; grid-template-columns:repeat(4,1fr); gap:1rem; list-style:none; padding:0}
.process-steps li{background:var(--card); padding:1rem; border-radius:12px; text-align:center}
.lead-magnet{padding:2.4rem 0}
.magnet-grid{display:grid; grid-template-columns:1fr 220px; gap:1rem; align-items:center}
.lead-form{display:flex; gap:0.5rem; margin-top:0.8rem}
.lead-form input{flex:1; padding:0.6rem; border-radius:8px; border:1px solid #e6d6c8}
.lead-form button{border-radius:8px}
.faq{padding:2rem 0}
.faq-list details{background:var(--card); padding:0.9rem; border-radius:10px; margin-bottom:0.6rem}
.cta-band{padding:2rem 0; background:linear-gradient(90deg, rgba(192,88,63,0.06), rgba(231,182,122,0.03)); border-radius:12px}
.footer-grid{display:grid; grid-template-columns:1fr 1fr 1fr; gap:1rem; align-items:start}
.site-footer{padding:2rem 0}
.meta{padding-top:1rem; color:var(--muted); font-size:0.9rem}
/* Responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr; text-align:center}
  .hero-art{order:-1}
  .cards{grid-template-columns:1fr}
  .process-steps{grid-template-columns:1fr 1fr}
  #nav-toggle{display:inline-block}
  .nav a:not(.cta){display:none}
}
@media (max-width:520px){
  .process-steps{grid-template-columns:1fr}
  .magnet-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"// Small interactive helpers: nav toggle, lead magnet form, FAQ state
document.addEventListener('DOMContentLoaded',function(){
  // Year in footer
  var y=document.getElementById('year'); if(y) y.textContent = new Date().getFullYear();

  // Mobile nav
  var navToggle=document.getElementById('nav-toggle');
  var mainNav=document.getElementById('main-nav');
  navToggle && navToggle.addEventListener('click',function(){
    var expanded = this.getAttribute('aria-expanded') === 'true';
    this.setAttribute('aria-expanded', String(!expanded));
    var links = mainNav.querySelectorAll('a');
    links.forEach(function(a){ a.style.display = expanded ? null : 'inline-block'; });
  });

  // Lead form: simple validation and friendly message
  var leadForm = document.getElementById('lead-form');
  if(leadForm){
    leadForm.addEventListener('submit', function(e){
      e.preventDefault();
      var email = leadForm.querySelector('input[name="email"]').value;
      if(!email || !/.+@.+\..+/.test(email)){
        alert('Please enter a valid email.');
        return;
      }
      // simulate download / subscribe
      leadForm.innerHTML = '<p class="success">Thanks — check your inbox for the guide.</p>';
      // In a real build, post to your mailing endpoint here.
    });
  }

  // FAQ: allow only one open at a time
  var details = document.querySelectorAll('.faq-list details');
  details.forEach(function(d){
    d.addEventListener('toggle', function(){
      if(this.open){
        details.forEach(function(other){ if(other !== d) other.open = false; });
      }
    });
  });

  // Smooth links for anchors
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault(); var id=this.getAttribute('href').slice(1); var el=document.getElementById(id);
      if(el) el.scrollIntoView({behavior:'smooth', block:'start'});
    });
  });
});
"} 
